package saver

import (
	"context"
	"testing"
)

type gsrWitnessStore struct {
	calls int
}

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	s.calls++
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	store := &gsrWitnessStore{}
	_ = Save(ctx, store, "id1", "a", "b")

	if store.calls >= 2 {
		t.Fatalf("Save() with a cancelled context performed %d Put calls, want < 2", store.calls)
	}
}

