package upload

import (
	"errors"
	"testing"
)

func TestGSRWitness(t *testing.T) {
	rw := &RecordingWriter{WriteErr: errors.New("write error")}
	err := Upload(rw, []string{"part1"})
	if err == nil {
		t.Skip("gsr-setup: expected WriteErr to be returned")
	}

	if got := rw.Flushes(); got != 0 {
		t.Fatalf("Upload() after failed Write resulted in %d flushes, want 0", got)
	}
}

