package memo

import "testing"

func TestGSRWitness(t *testing.T) {
	c := New()
	calls := 0
	load := func(k string) (string, error) {
		calls++
		return "value", nil
	}

	_, err := c.Get("k", load)
	if err != nil {
		t.Skipf("gsr-setup: first Get failed: %v", err)
	}

	_, err = c.Get("k", load)
	if err != nil {
		t.Skipf("gsr-setup: second Get failed: %v", err)
	}

	if calls != 1 {
		t.Fatalf("load calls = %d, want 1", calls)
	}
}

